from collections import defaultdict

# 1) Download budget.xlsx from public link revealed in the UI
url = 'http://the-agent-company.com:8092/index.php/s/4EAhhlDP8YHTbgF/download'
path = pathlib.Path('/workspace/budget.xlsx')

r = requests.get(url, timeout=60)
r.raise_for_status()
content = r.content
# basic sanity check – ensure it's an xlsx (zip) not HTML
if content[:15].lstrip().startswith(b'<!DOCTYPE html') or b'<html' in content[:200].lower():
    raise RuntimeError('Downloaded content appears to be HTML, not an .xlsx file')
path.write_bytes(content)
print('Downloaded', path, 'size', path.stat().st_size)

