with zipfile.ZipFile(io.BytesIO(content)) as zf:
    names = zf.namelist()[:10]
print('Zip ok. First entries:', names)

# 2) Parse Excel and compute totals per department
import openpyxl
from decimal import Decimal, InvalidOperation

def parse_amount(val):
    if val is None:
        return Decimal('0')
    if isinstance(val, (int, float)):
        return Decimal(str(val))
    s = str(val)
    s = s.replace(',', '')
    s = re.sub(r'[^0-9.+-]', '', s)
    if s in ('', '+', '-', '.', '+.', '-.'):
        return Decimal('0')
    try:
        return Decimal(s)
    except InvalidOperation:
        return Decimal('0')

wb = openpyxl.load_workbook(path, data_only=True)
print('Sheets:', wb.sheetnames)

totals = defaultdict(Decimal)

for ws in wb.worksheets:
    # Find header row containing Department and an amount-like column
    header_row_idx = None
    dept_col = None
    amount_col = None
    for r in range(1, min(ws.max_row, 50)+1):
        row_vals = [ws.cell(r, c).value for c in range(1, min(ws.max_column, 50)+1)]
        lowered = [str(v).strip().lower() if v is not None else '' for v in row_vals]
        # potential column matches
        for c, v in enumerate(lowered, start=1):
            if v in ('department', 'dept'):
                dept_col = c
        for c, v in enumerate(lowered, start=1):
            if v in ('amount', 'budget', 'total', 'total amount', 'budgeted amount'):
                amount_col = c
        if dept_col and amount_col:
            header_row_idx = r
            break
    if not (header_row_idx and dept_col and amount_col):
        continue
    # iterate rows beneath header
    for r in range(header_row_idx+1, ws.max_row+1):
        d = ws.cell(r, dept_col).value
        a = ws.cell(r, amount_col).value
        if d is None and (a is None or a == ''):
            # stop when long stretch of empties; but be simple
            continue
        dept = str(d).strip() if d is not None else ''
        if dept == '':
            continue
        amt = parse_amount(a)
        totals[dept] += amt

# If nothing parsed, try a simple heuristic on the first sheet: assume first row is header
if not totals and wb.worksheets:
    ws = wb.worksheets[0]
    header = [str(ws.cell(1,c).value).strip().lower() if ws.cell(1,c).value is not None else '' for c in range(1, ws.max_column+1)]
    try:
        dept_col = header.index('department')+1
    except ValueError:
        dept_col = None
    # prefer amount, then budget
    amount_labels = ['amount','budget','total','total amount','budgeted amount']
    amount_col = None
    for label in amount_labels:
        if label in header:
            amount_col = header.index(label)+1
            break
    if dept_col and amount_col:
        for r in range(2, ws.max_row+1):
            d = ws.cell(r, dept_col).value
            a = ws.cell(r, amount_col).value
            if d is None and (a is None or a == ''):
                continue
            dept = str(d).strip() if d is not None else ''
            if dept == '':
                continue
            totals[dept] += parse_amount(a)

print('Parsed departments:', len(totals))
for k,v in list(totals.items())[:10]:
    print(' ', k, '->', f'{v:.2f}')

# 3) Write CSV summary
csv_path = pathlib.Path('/workspace/budget_summary.csv')
with csv_path.open('w', newline='') as f:
    w = csv.writer(f)
    w.writerow(['Department','Total_Amount'])
    for dept, amt in sorted(totals.items()):
        w.writerow([dept, f'{amt:.2f}'])

print('Wrote CSV to', csv_path)

